 static void publish(Map<String,Object> m){ContentResolver.values=m;check(HomeLayoutNativeEndpointOS4.refreshFromProvider());}
 static void join(Thread t){try{t.join(5000);check(!t.isAlive());}catch(InterruptedException e){throw new AssertionError(e);}}
 static class Gate {final CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);void waitEntered(){try{check(entered.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}}void block(){entered.countDown();try{check(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new AssertionError(e);}}}
