 run("framework same blocked fingerprint remains denied",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","API_TOO_LOW","framework_check_name","FixtureFramework","framework_check_version","102-test","framework_check_version_code",102L));eq(receive(),0);});
 for(String part:new String[]{"name","version","version_code"})run("framework changed fingerprint permits same override as Java entry "+part,()->{var m=prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","SERVICE_ERROR","framework_check_name","FixtureFramework","framework_check_version","102-test","framework_check_version_code",102L,"home_title_hide_report_text",true);m.put("prefs_key_framework_check_"+part,part.equals("version_code")?101L:"previous");publish(m);eq(receive(),33);});
 run("framework whitespace normalization matches Java entry",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","API_TOO_LOW","framework_check_name"," FixtureFramework ","framework_check_version"," 102-test ","framework_check_version_code",102L));eq(receive(),0);});
 run("missing reason cannot authorize changed framework",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_name","old"));eq(receive(),0);});
 run("empty reason cannot authorize changed framework",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","","framework_check_name","old"));eq(receive(),0);});
 run("unavailable runtime cannot authorize override",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","SERVICE_ERROR","framework_check_name","old"));BaseLoad.unavailable=true;eq(receive(),0);BaseLoad.unavailable=false;BaseLoad.fail=true;eq(receive(),0);});
 run("allowed stored gate does not require runtime fingerprint",()->{publish(prefs("allow_hook",true,"framework_api_allow_hook",true));BaseLoad.fail=true;eq(receive(),1);});
 run("global hook off overrides changed framework",()->{publish(prefs("allow_hook",false,"framework_api_allow_hook",false,"framework_check_reason","SERVICE_ERROR","framework_check_name","old"));eq(receive(),0);});
 run("64bit framework version code is not truncated",()->{long code=4294967398L;BaseLoad.versionCode=code;publish(prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","API_TOO_LOW","framework_check_name","FixtureFramework","framework_check_version","102-test","framework_check_version_code",code));eq(receive(),0);BaseLoad.versionCode=102L;eq(receive(),1);});
 for(Object[] wrong:new Object[][]{{"framework_check_reason",1},{"framework_check_name",1L},{"framework_check_version",false},{"framework_check_version_code",102},{"framework_check_version_code","102"}})run("wrong framework metadata type rejects whole revision "+Arrays.toString(wrong),()->{publish(prefs("allow_hook",true));ContentResolver.values=prefs("allow_hook",true,wrong[0],wrong[1]);check(!HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),-1);});
 run("framework fields and gate share one physical revision",()->{Gate g=new Gate();ContentResolver.values=prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","SERVICE_ERROR","framework_check_name","old");ContentResolver.afterSnapshot=g::block;AtomicBoolean ok=new AtomicBoolean();Thread t=new Thread(()->ok.set(HomeLayoutNativeEndpointOS4.refreshFromProvider()));t.start();g.waitEntered();ContentResolver.values=prefs("allow_hook",true,"framework_api_allow_hook",false,"framework_check_reason","SERVICE_ERROR","framework_check_name","FixtureFramework","framework_check_version","102-test","framework_check_version_code",102L);g.release.countDown();join(t);check(ok.get());eq(receive(),1);ContentResolver.afterSnapshot=()->{};check(HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),0);});
 String[] feature={"home_other_high_models","home_other_disable_prestart","home_dock_bg_custom_enable","home_title_hide_report_text"};int[] bits={2,4,16,32};
 for(int i=0;i<feature.length;i++){final int k=i;run("exact feature bit "+feature[i],()->{publish(prefs("allow_hook",true,feature[k],true));eq(receive(),1|bits[k]);});}
 run("soft glass requires active dock",()->{publish(prefs("allow_hook",true,"home_dock_add_blur","1"));eq(receive(),1);publish(prefs("allow_hook",true,"home_dock_bg_custom_enable",true,"home_dock_add_blur","1"));eq(receive(),25);});
 run("all supported features produce exactly63",()->{publish(prefs("allow_hook",true,"home_other_high_models",true,"home_other_disable_prestart",true,"home_dock_bg_custom_enable",true,"home_dock_add_blur","1","home_title_hide_report_text",true));eq(receive(),63);});
 run("unknown blur choice does not set soft glass",()->{publish(prefs("allow_hook",true,"home_dock_bg_custom_enable",true,"home_dock_add_blur","99"));eq(receive(),17);});
 run("fresh snapshot accepted and older than5 seconds rejected",()->{publish(prefs("allow_hook",true));set("hyosSnapshotAtNanos",System.nanoTime()-1_000_000_000L);eq(receive(),1);set("hyosSnapshotAtNanos",System.nanoTime()-6_000_000_000L);eq(receive(),-1);});
 run("hot reload restored map never resurrects live authorization",()->{BaseHook.putHotReloadRuntimeState("OS4.HomeLayout.ProviderSnapshot.v1",Map.of("allow_hook",1,"home_title_hide_report_text",1));eq(receive(),-1);check(get("cachedValues")!=null);publish(prefs("allow_hook",true));eq(receive(),1);});
 run("fresh success then unavailable retires native authorization but preserves layout cache",()->{publish(prefs("allow_hook",true));Object cache=get("cachedValues");ContentResolver.failure="query";check(!HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),-1);check(get("cachedValues")==cache);ContentResolver.failure="";publish(prefs("allow_hook",true,"home_title_hide_report_text",true));eq(receive(),33);});
 run("explicit settings clear resets enabled flags",()->{publish(prefs("allow_hook",true,"home_title_hide_report_text",true));eq(receive(),33);publish(Map.of());eq(receive(),0);});
 for(String mode:new String[]{"getAll","query","null","empty","columns","columnName","nullSchema","schema1","read","close"})run("malformed provider revokes fresh authorization "+mode,()->{publish(prefs("allow_hook",true));ContentResolver.failure=mode;check(!HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),-1);});
 for(Object wrong:new Object[]{1,"true",1L})run("provider boolean wrong type refused "+wrong.getClass().getSimpleName(),()->{ContentResolver.values=prefs("allow_hook",wrong);check(!HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),-1);});
 for(Object wrong:new Object[]{1,"invalid","2147483648"})run("provider string preference wrong representation refused "+wrong,()->{ContentResolver.values=prefs("allow_hook",true,"home_dock_add_blur",wrong);check(!HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),-1);});
 run("wrong interface token throws before access",()->{publish(prefs("allow_hook",true));boolean threw=false;try{endpoint().receiveHyosFlags(new Parcel("wrong"),0);}catch(SecurityException expected){threw=true;}check(threw);});
