 for(int[] pair:new int[][]{{9999,42},{10100,0},{10100,-1},{10101,42},{10100,43}})run("caller gate refuses "+Arrays.toString(pair),()->{publish(prefs("allow_hook",true));Binder.setCallingIdentityForTest(pair[0],pair[1]);eq(receive(),-1);});
 run("UID must have exact Home package",()->{check(HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(10100));PackageManager.packages=new String[]{"com.miui.home.fake"};check(!HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(10100));PackageManager.packages=null;check(!HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(10100));PackageManager.packages=new String[]{"com.other","com.miui.home"};check(HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(10100));check(!HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(1000));});
 run("package service failure cannot authorize caller",()->{PackageManager.fail=true;check(!HomeLayoutNativeEndpointOS4.uidBelongsToLauncher(10100));});
