 run("atomic real provider getAll revision survives concurrent settings change",()->{Gate g=new Gate();ContentResolver.values=prefs("allow_hook",true,"home_other_high_models",true);ContentResolver.afterSnapshot=g::block;AtomicBoolean ok=new AtomicBoolean();Thread t=new Thread(()->ok.set(HomeLayoutNativeEndpointOS4.refreshFromProvider()));t.start();g.waitEntered();ContentResolver.values=prefs("allow_hook",false,"home_title_hide_report_text",true);g.release.countDown();join(t);check(ok.get());eq(receive(),3);ContentResolver.afterSnapshot=()->{};check(HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),0);});
 run("inflight refresh cannot publish after hot reload retirement",()->{Gate g=new Gate();ContentResolver.values=prefs("allow_hook",true);ContentResolver.afterSnapshot=g::block;set("refresher",null);AtomicBoolean ok=new AtomicBoolean(true);Thread t=new Thread(()->ok.set(HomeLayoutNativeEndpointOS4.refreshFromProvider()));t.start();g.waitEntered();check(HomeLayoutNativeEndpointOS4.pauseForHotReload());g.release.countDown();join(t);check(!ok.get());eq(receive(),-1);HomeLayoutNativeEndpointOS4.resumeAfterRejectedHotReload();set("refresher",new Thread());ContentResolver.afterSnapshot=()->{};check(HomeLayoutNativeEndpointOS4.refreshFromProvider());eq(receive(),1);});
